164:       [55, 82.4].forEach((frequency, index) => { const oscillator = audioContext.createOscillator(); const gain = audioContext.createGain(); oscillator.type = 'sine'; oscillator.frequency.value = frequency; gain.gain.value = index ? 0.35 : 0.6; oscillator.connect(gain); gain.connect(master); oscillator.start(); });
165:       soundOn = true; label.textContent = 'Sound on';
