const translations = {
  en: {
    ui: {
      saveTitle: 'A story about choosing', sound: 'Sound off', art: 'THE OUTER REACHES · 02:17 AM', eyebrow: 'A choice-driven fantasy story', title: 'The island<br>that <em>chose you.</em>', deck: 'You came to Geyropoa alone. Its devilish residents have been waiting for you—but a heart can’t be claimed by a spell.', meta: '✦ 3 possible companions|◷ 10–15 minutes|♡ Multiple endings', begin: 'Begin your story <span>→</span>', continue: 'Continue saved story <span>↗</span>', note: 'All characters are adults (18+). A gentle, non-explicit romance.', orbit: 'NOBODY OWNS<br>A HEART', chapter: 'CHAPTER 01', chapterName: 'THE STRANGE SHORE', cast: 'THE ISLANDERS', restart: '↺ Start over', choiceHeading: 'WHAT WILL YOU DO?', playAgain: 'Play again <span>↺</span>', titleButton: 'Back to title', footerHint: 'Your choices shape the story.', footerTitle: 'THE HEART-TIDE', footerSub: 'AN INTERACTIVE STORY <i>·</i> MADE FOR THE MOONLIT HOURS', saveProgress: 'Progress saved locally', saveEnding: 'Ending reached · Saved locally', saveWaiting: 'A story is waiting for you', confirmRestart: 'Start a new story? Your current saved progress will be replaced.', night: 'GEYROPOA · NIGHT', dawn: 'GEYROPOA · BEFORE DAWN', endingKicker: 'THE END', endingSub: 'YOUR STORY CONTINUES', thanks: 'Thank you for visiting Geyropoa.', storyHint: 'Your choices shape the story.', soundOn: 'Sound on', soundUnavailable: 'Sound unavailable', chapterTide: 'THE HEART-TIDE', firstLight: 'GEYROPOA · FIRST LIGHT', choiceMark: 'YOUR CHOICE', storySuffix: '’S STORY', routeLabel: 'THE', age: '18+'
    },
    arrival: {
      title: 'A shore without footprints',
      text: 'Your boat drifts into a cove beneath a violet moon. You are the only arrival Geyropoa has seen in years. Three young demon women wait on the beach, each with a different kind of wonder in her eyes.\n\nThey introduce themselves as Lyra, Vesper, and Mara. All three are adults, eighteen or older. Each confesses that the island’s old heart-tide has filled her with a sudden, impossible love for you.\n\nBut they do not ask you to believe a spell. They ask you to stay long enough to meet the people they are when the magic grows quiet.',
      quote: '“You get to choose,” Lyra says. “And so do we.”',
      choices: [ ['Meet Lyra at the lighthouse.', 'A keeper who wants to decide what her light is for.'], ['Follow Vesper to her map room.', 'A cartographer looking for a road beyond the island.'], ['Walk with Mara through the moon garden.', 'A gardener making plans for a life of her own.'], ['Ask about the heart-tide.', 'Find out how to break the spell before choosing anyone.'] ]
    },
    truth: { eyebrow: 'GEYROPOA · THE ISLAND’S HEART', title: 'The spell beneath the tide', text: 'At the island’s center, you find a pool of black water ringed with old runes. Vesper’s map fits the stones. The heart-tide is not a curse exactly—it magnifies longing until it feels like destiny.\n\nThe three women can break it, but only if someone speaks the thing the spell cannot understand: love is a choice, not a debt. You could say the words and leave all three free to discover what they truly feel.', quote: 'The tide stills. The island waits.', choice: ['Break the heart-tide.', 'Give every heart back to its owner.'] },
    commitment: { title: 'What will you choose?', quote: '“I care for you,” she says. “But I want your answer to be yours. What do you want our story to be?”', choices: [['Choose a romance together.', 'Be honest about the feelings you want to explore.'], ['Choose a lasting friendship.', 'Care for each other without becoming a couple.'], ['Set out alone.', 'Decline romance and leave room for everyone to choose freely.']] },
    endings: {
      truth: { eyebrow: 'GEYROPOA · FIRST LIGHT', title: 'A heart, set free', text: 'You walk to the island’s heart and speak the truth aloud: nobody owes love to a spell. The heart-tide breaks like a wave of warm light.\n\nLyra is free to tend her beacon for herself. Vesper can draw a map that leads anywhere. Mara can choose where to plant her seeds. They thank you—not as someone who rescued them, but as the first person who let them choose.\n\nAlone on the shore, you watch the sunrise and wonder what you might choose next.' },
      romanceTitleBond: 'A future with', romanceTitleNoBond: 'A beginning with', friendTitle: 'A friendship with', soloTitle: 'The road you take alone',
      solo: 'You thank {name} for trusting you with the truth. You do not promise a romance you cannot give. She looks a little sad, then smiles with relief.\n\nThe three islanders watch you leave together as friends, free to write their own next chapters. You sail toward the mainland beneath a sky full of unfamiliar stars. Choosing honestly is its own kind of kindness.'
    },
    continuing: 'The heart-tide is fading. Soon, the island’s pull will be gone, and every feeling left here will belong to the person who feels it.',
    goodbyeEnding: 'Thank you for visiting Geyropoa.',
    sound: { on: 'Sound on', off: 'Sound off', unavailable: 'Sound unavailable' }
  },
  tr: {
    ui: {
      saveTitle: 'Seçimlerle şekillenen bir hikâye', sound: 'Ses kapalı', art: 'DIŞ KIYILAR · 02:17', eyebrow: 'Seçimlerle şekillenen bir fantastik hikâye', title: 'Seni <em>seçen</em><br>ada.', deck: 'Geyropoa’ya tek başına geldin. Şeytani sakinleri seni bekliyordu; ama bir kalp büyüyle kazanılamaz.', meta: '✦ 3 olası yol arkadaşı|◷ 10–15 dakika|♡ Birden fazla son', begin: 'Hikâyene başla <span>→</span>', continue: 'Kayıtlı hikâyeye devam et <span>↗</span>', note: 'Tüm karakterler yetişkindir (18+). Nazik ve açık sahneler içermeyen bir romantizm.', orbit: 'HİÇ KİMSE BİR<br>KALBİN SAHİBİ DEĞİL', chapter: 'BÖLÜM 01', chapterName: 'İZİ OLMAYAN KIYI', cast: 'ADA SAKİNLERİ', restart: '↺ Baştan başla', choiceHeading: 'NE YAPACAKSIN?', playAgain: 'Yeniden oyna <span>↺</span>', titleButton: 'Başlık ekranına dön', footerHint: 'Seçimlerin hikâyeyi şekillendiriyor.', footerTitle: 'KALP GELGİTİ', footerSub: 'ETKİLEŞİMLİ BİR HİKÂYE <i>·</i> AY IŞIĞINDAKİ SAATLER İÇİN', saveProgress: 'İlerleme cihaza kaydedildi', saveEnding: 'Son kaydedildi', saveWaiting: 'Hikâyen seni bekliyor', confirmRestart: 'Yeni bir hikâyeye başlansın mı? Mevcut kayıtlı ilerlemen silinecek.', night: 'GEYROPOA · GECE', dawn: 'GEYROPOA · ŞAFAKTAN ÖNCE', endingKicker: 'SON', endingSub: 'HİKÂYEN DEVAM EDİYOR', thanks: 'Geyropoa’yı ziyaret ettiğin için teşekkürler.', storyHint: 'Seçimlerin hikâyeyi şekillendiriyor.', soundOn: 'Ses açık', soundUnavailable: 'Ses kullanılamıyor', chapterTide: 'KALP GELGİTİ', firstLight: 'GEYROPOA · İLK IŞIK', choiceMark: 'SEÇİMİN', storySuffix: '’IN HİKÂYESİ', routeLabel: '', age: '18+'
    },
    cast: {
      lyra: { name: 'Lyra', role: 'Deniz feneri bekçisi', initial: 'L', avatar: 'lyra', title: 'Söndürmediği ışık', quote: '“Yalnızca ışığımı değil, beni de gören birini istiyorum.”', text: 'Adanın ucunda Lyra, yüz yıldır ışığı yanmayan bir deniz fenerine göz kulak oluyor. Alevi sönmüş değil; adanın nasıl bir yer olacağına birinin karar vermesini bekliyor.\n\nKalp gelgitinin ona sana âşık olduğundan emin hissettirdiğini itiraf ediyor. Bu duygu hâlâ içinde, ama büyünün kimseyi sürüklemediği bir anda geriye ne kalacağını bilmek istiyor.', choices: [['Feneri birlikte yeniden yakmasına yardım et.', 'İşi paylaşır, cesur görünüşünün ardındaki umudu görmesine izin verirsin.', 1], ['Ada özgür olsaydı ne yapacağını sor.', 'Lyra ilk kez kendi istediği gelecekten söz eder.', 0]], romance: ['Birlikte fenerle ilgileniyorsunuz; bekçiyle misafir olarak değil, kalmaya karar vermiş iki insan olarak. Yeni ışığı ana karaya ulaştığında Lyra elini tutuyor. Ada hâlâ gizemli; her yeni şafağı birlikte karşılama kararınız ise tamamen size ait.', 'Fener, denizin üzerine gümüşten bir yol düşürüyor. Lyra, karşılıksız ve özgürce verilen sevginin nasıl hissettirdiğini keşfetmek için seninle yelken açmayı seçiyor. Geyropoa geride kalırken parmaklarını seninkilere doluyor; hikâyeniz daha yeni başlıyor.'], friend: 'Feneri Lyra’nın emin ellerine bırakıp ona yazacağına söz veriyorsun. Sana bir kez sarılıyor, sonra kendi seçtiği ışığa dönüyor. Bu bir aşk değil; ama daha az değerli de değil.' },
      vesper: { name: 'Vesper', role: 'Haritacı', initial: 'V', avatar: 'vesper', title: 'Ucu olmayan bir harita', quote: '“Buradaki bütün yolları çizdim. Nereye gitmek istediğimi hiç sormadım.”', text: 'Vesper, siyah cam parçalarının üzerine haritalar çiziyor. Çizdiği her yol, kalp gelgitinin başladığı adanın merkezine geri kıvrılıyor. Bu örüntü onu büyülüyor; ne anlama geldiğinden ise sessizce korkuyor.\n\nBüyünün onu seni ilk gördüğü anda âşık ettiğini söylüyor. İkinizden hiçbiri adına bu büyünün karar vermesini istemiyor.', choices: [['Onunla imkânsız yolu takip et.', 'Merakına güveniyor, o da sakladığı haritayı seninle paylaşıyor.', 1], ['Birlikte kaybolmayı tercih ettiğini söyle.', 'Vesper gülüyor ve ilk kez haritayı tamamlamadan bırakıyor.', 0]], romance: ['Harita, BURASI diye işaretlenmiş boş bir yerde sona eriyor. Vesper geri kalanını seninle, haritada olmayan günler boyunca keşfetmek istediğini söylüyor. Henüz adını koymadığı bir göğün altında öpüşüyorsunuz; gelecek, güzel bir bilinmezlik gibi.', 'Vesper atlasını kapatıp seninle açık yola çıkmayı seçiyor. Harita öyle gösterdiği için değil, gerçekten istediği için elini tutuyor. Geyropoa’nın ötesinde her yön yeni.'], friend: 'Vesper sana adadan dışarı çıkan tek bir yolun olduğu küçük bir harita veriyor. “Hazır olduğunda,” diyor. Gerçek bir dostlukla, büyüye ihtiyaç duymadan vedalaşıyorsunuz.' },
      mara: { name: 'Mara', role: 'Yabanın koruyucusu', initial: 'M', avatar: 'mara', title: 'Dünyanın ucundaki bahçe', quote: '“Gelgit dindiğinde bile kendi kalbimin sesini duymak istiyorum.”', text: 'Mara, çiçeklerin konuşan kişiye döndüğü ay ışıklı bahçelerde yaşıyor. Adanın kalp gelgitinin zayıfladığını biliyor; büyü ve bildiği yuva yok olup giderse diye tohum biriktiriyor.\n\nSana yakınlık duyduğunu söylüyor ama duygularının gerçekten kendisine ait olmasını istiyor. İkiniz de bunun ne anlama geldiğini keşfedebilirsiniz.', choices: [['Yeni bir bahçe için Mara’yla tohum topla.', 'Adanın ötesinde kurmayı umduğu bahçeyi seninle paylaşıyor.', 1], ['Ona en sevdiği sessiz yeri göstermesini rica et.', 'Büyülü çiçeklerden uzak, sadece kendisi olabildiği bir yere götürüyor seni.', 0]], romance: ['Mara, Geyropoa’nın ötesindeki toprağa ilk tohumu ekiyor. Kader öyle yazdığı için değil, yanında kendini güvende hissedip hayal kurabildiği için orada bir yuva kurmasına yardım etmeni istiyor. Kabul ediyorsun ve sıradan, güzel bir şafağın altında seni öpüyor.', 'Mara, yanında bir avuç tohumla seninle yola çıkmayı seçiyor. Onları ekecek bir yer bulmasına yardım edeceğine söz veriyorsun. Gülümsemesi yumuşak, kararlı ve tamamen kendisine ait.' ], friend: 'Mara’nın yola hazırladığı tohumları toplamasına yardım ediyorsun. Sen giderken o bahçeye bakacak; geri döneceğine söz veriyorsun. Adanın kır çiçekleri sana el sallarken dostça vedalaşıyorsunuz.' }
    },
    arrival: { title: 'İzi olmayan kıyı', text: 'Teknen, mor bir ayın altındaki koya doğru süzülüyor. Geyropoa’ya yıllardır gelen ilk kişisin. Sahilde, gözlerinde bambaşka bir merak taşıyan üç genç şeytan kız seni bekliyor.\n\nKendilerini Lyra, Vesper ve Mara olarak tanıtıyorlar. Üçü de yetişkin; on sekiz yaşında ya da daha büyük. Her biri, adanın eski kalp gelgitinin içinde sana karşı ansızın ve imkânsız bir aşk yarattığını itiraf ediyor.\n\nAma büyüye inanmanı istemiyorlar. Büyü dindiğinde kim olduklarını tanıyabilmen için biraz kalmanı istiyorlar.', quote: '“Seçim senin,” diyor Lyra. “Bizimki de öyle.”', choices: [['Lyra’yla deniz fenerinde buluş.', 'Işığının neye yarayacağına kendi karar vermek isteyen bir bekçi.'], ['Vesper’i harita odasına kadar takip et.', 'Adanın ötesine uzanan bir yol arayan haritacı.'], ['Mara’yla ay bahçesinde yürü.', 'Kendi hayatının planlarını yapan bir bahçıvan.'], ['Kalp gelgitini sor.', 'Birini seçmeden önce büyüyü nasıl bozacağını öğren.']] },
    truth: { eyebrow: 'GEYROPOA · ADANIN KALBİ', title: 'Gelgitin altındaki büyü', text: 'Adanın merkezinde, eski rünlerle çevrili siyah bir su birikintisi buluyorsun. Vesper’in haritası taşlara uyuyor. Kalp gelgiti tam olarak bir lanet değil; özlemi, kader gibi hissedilene dek büyütüyor.\n\nÜç kadın büyüyü bozabilir, ama önce büyünün anlayamayacağı bir şeyi söylemek gerekiyor: aşk bir borç değil, seçimdir. Bu sözleri söyleyerek üçünün de gerçek duygularını özgürce keşfetmesini sağlayabilirsin.', quote: 'Gelgit duruluyor. Ada bekliyor.', choice: ['Kalp gelgitini boz.', 'Her kalbi sahibine geri ver.'] },
    commitment: { title: 'Ne seçeceksin?', quote: '“Sana değer veriyorum,” diyor. “Ama cevabının sana ait olmasını istiyorum. Bizim hikâyemiz nasıl olsun?”', choices: [['Birlikte aşkı seçin.', 'Keşfetmek istediğin duygular konusunda dürüst ol.'], ['Kalıcı bir dostluk seçin.', 'Bir çift olmadan da birbirinizi önemseyin.'], ['Tek başına yola çık.', 'Aşkı reddet ve herkesin özgürce seçim yapmasına izin ver.']] },
    endings: { truth: { eyebrow: 'GEYROPOA · İLK IŞIK', title: 'Özgür kalan bir kalp', text: 'Adanın kalbine yürüyüp gerçeği yüksek sesle söylüyorsun: hiç kimse büyüye aşk borçlu değil. Kalp gelgiti, ılık bir ışık dalgası gibi kırılıyor.\n\nLyra artık fenerine kendi isteğiyle bakabilir. Vesper istediği yere giden bir harita çizebilir. Mara tohumlarını nereye ekeceğine karar verebilir. Sana onları kurtardığın için değil, seçim hakkı tanıyan ilk kişi olduğun için teşekkür ediyorlar.\n\nKıyıda tek başına gün doğumunu izliyor ve sırada neyi seçeceğini merak ediyorsun.' }, romanceTitleBond: ' ile bir gelecek', romanceTitleNoBond: ' ile bir başlangıç', friendTitle: ' ile dostluk', soloTitle: 'Tek başına seçtiğin yol', solo: '{name}’e gerçeği seninle paylaştığı için teşekkür ediyorsun. Veremeyeceğin bir aşkın sözünü vermiyorsun. Biraz üzülüyor, ardından rahatlamış bir gülümsemeyle karşılık veriyor.\n\nÜç ada sakini, kendi hikâyelerini yazmakta özgür dostlar olarak vedalaşmanı izliyor. Bilinmedik yıldızlarla dolu göğün altında ana karaya yelken açıyorsun. Dürüstçe seçim yapmak da başlı başına bir iyilik.' },
    continuing: 'Kalp gelgiti zayıflıyor. Çok yakında adanın çekimi sona erecek ve geriye kalan her duygu, onu hisseden kişiye ait olacak.',
    sound: { on: 'Ses açık', off: 'Ses kapalı', unavailable: 'Ses kullanılamıyor' }
