20: const state = { screen: 'title', node: 'arrival', route: null, bond: 0, chapter: 1 };
21: const STORAGE_KEY = 'geyropoa-heart-tide-save-v1';
22: let audioContext = null;
23: let soundOn = false;
24: 
25: function save() {
26:   try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (_) {}
27:   $('saveStatus').textContent = state.screen === 'ending' ? 'Ending reached · Saved locally' : 'Progress saved locally';
28: }
29: function showTitle() {
30:   $('storyScreen').classList.add('hidden');
31:   $('welcomeScreen').classList.remove('hidden');
32:   const saved = readSave();
33:   $('continueButton').classList.toggle('hidden', !saved || saved.screen === 'title');
34:   $('saveStatus').textContent = saved && saved.screen !== 'title' ? 'A story is waiting for you' : 'A story about choosing';
35: }
36: function readSave() {
37:   try { const data = JSON.parse(localStorage.getItem(STORAGE_KEY)); return data && data.node ? data : null; } catch (_) { return null; }
38: }
39: function begin() {
40:   Object.assign(state, { screen: 'story', node: 'arrival', route: null, bond: 0, chapter: 1 });
41:   render();
42: }
43: function continueStory() {
44:   const saved = readSave();
45:   if (saved) Object.assign(state, saved);
46:   state.screen = 'story';
47:   render();
48: }
49: function openStory() {
50:   $('welcomeScreen').classList.add('hidden');
51:   $('storyScreen').classList.remove('hidden');
52: }
53: function setText(element, text) {
54:   element.textContent = text;
55: }
56: function renderCast() {
57:   $('castList').innerHTML = Object.entries(cast).map(([key, person]) => `<div class="cast-person ${state.route === key ? 'active' : ''}"><div class="avatar ${person.avatar}">${person.initial}</div><div><span class="person-name">${person.name}</span><span class="person-role">${person.role}</span></div></div>`).join('');
58: }
59: function makeChoice(label, detail, action, glyph = '✦') {
60:   const button = document.createElement('button');
61:   button.className = 'choice-button';
62:   button.innerHTML = `<span class="choice-glyph" aria-hidden="true">${glyph}</span><span>${label}${detail ? `<small>${detail}</small>` : ''}</span>`;
63:   button.addEventListener('click', action);
64:   return button;
65: }
66: function displayScene({ eyebrow = 'GEYROPOA · NIGHT', title, text, quote = '', choices = [], ending = false }) {
67:   openStory();
68:   $('sceneEyebrow').textContent = eyebrow;
69:   $('sceneTitle').textContent = title;
70:   $('sceneText').textContent = text;
71:   $('sceneQuote').textContent = quote;
72:   $('sceneQuote').classList.toggle('hidden', !quote);
73:   $('choiceHeading').classList.toggle('hidden', ending);
74:   $('choices').classList.toggle('hidden', ending);
75:   $('endingActions').classList.toggle('hidden', !ending);
76:   $('choices').replaceChildren();
77:   choices.forEach((choice) => $('choices').appendChild(makeChoice(...choice)));
78:   $('chapterKicker').textContent = ending ? 'THE END' : `CHAPTER 0${state.chapter}`;
79:   $('chapterSmall').textContent = ending ? 'YOUR STORY CONTINUES' : (state.node === 'arrival' ? 'THE STRANGE SHORE' : state.route ? `${cast[state.route].name.toUpperCase()}’S STORY` : 'THE HEART-TIDE');
80:   $('progressFill').style.width = ending ? '100%' : state.node === 'arrival' ? '16%' : state.node === 'truth' ? '66%' : state.node === 'commit' ? '78%' : '48%';
81:   $('footerHint').textContent = ending ? 'Thank you for visiting Geyropoa.' : 'Your choices shape the story.';
82:   renderCast();
83:   $('narrative-panel')?.classList.remove('fade-in');
84:   document.querySelector('.narrative-panel').classList.remove('fade-in');
85:   void document.querySelector('.narrative-panel').offsetWidth;
86:   document.querySelector('.narrative-panel').classList.add('fade-in');
87:   save();
88: }
89: function enterRoute(route) {
90:   state.route = route;
91:   state.node = 'route';
92:   state.chapter = 2;
93:   const person = cast[route];
94:   displayScene({ eyebrow: `${person.name.toUpperCase()} · THE ${person.role.toUpperCase()}`, title: person.title, text: person.text, quote: person.quote,
95:     choices: person.choices.map(([label, detail, points]) => [label, detail, () => { state.bond = points; state.node = 'commit'; state.chapter = 3; render(); }]) });
96: }
97: function ending(type) {
98:   state.node = 'ending';
99:   state.endingType = type;
100:   state.screen = 'ending';
101:   state.chapter = 4;
102:   if (type === 'truth') {
103:     displayScene({ eyebrow: 'GEYROPOA · FIRST LIGHT', title: 'A heart, set free', text: 'You walk to the island’s heart and speak the truth aloud: nobody owes love to a spell. The heart-tide breaks like a wave of warm light.\n\nLyra is free to tend her beacon for herself. Vesper can draw a map that leads anywhere. Mara can choose where to plant her seeds. They thank you—not as someone who rescued them, but as the first person who let them choose.\n\nAlone on the shore, you watch the sunrise and wonder what you might choose next.', ending: true });
104:     return;
105:   }
106:   const person = cast[state.route];
107:   let title, text;
108:   if (type === 'romance') {
109:     title = state.bond ? `A future with ${person.name}` : `A beginning with ${person.name}`;
110:     text = person.romance[state.bond ? 0 : 1];
111:   } else if (type === 'friend') {
112:     title = `A friendship with ${person.name}`;
113:     text = person.friend;
114:   } else {
115:     title = 'The road you take alone';
116:     text = `You thank ${person.name} for trusting you with the truth. You do not promise a romance you cannot give. She looks a little sad, then smiles with relief.\n\nThe three islanders watch you leave together as friends, free to write their own next chapters. You sail toward the mainland beneath a sky full of unfamiliar stars. Choosing honestly is its own kind of kindness.`;
117:   }
118:   displayScene({ eyebrow: `${person.name.toUpperCase()} · YOUR CHOICE`, title, text, ending: true });
119: }
120: function render() {
121:   state.screen = state.screen === 'ending' || state.node === 'ending' ? 'ending' : 'story';
122:   if (state.node === 'arrival') {
123:     state.screen = 'story';
124:     displayScene({ eyebrow: 'GEYROPOA · NIGHT', title: 'A shore without footprints', text: 'Your boat drifts into a cove beneath a violet moon. You are the only arrival Geyropoa has seen in years. Three young demon women wait on the beach, each with a different kind of wonder in her eyes.\n\nThey introduce themselves as Lyra, Vesper, and Mara. All three are adults, eighteen or older. Each confesses that the island’s old heart-tide has filled her with a sudden, impossible love for you.\n\nBut they do not ask you to believe a spell. They ask you to stay long enough to meet the people they are when the magic grows quiet.', quote: '“You get to choose,” Lyra says. “And so do we.”', choices: [
125:       ['Meet Lyra at the lighthouse.', 'A keeper who wants to decide what her light is for.', () => enterRoute('lyra')],
126:       ['Follow Vesper to her map room.', 'A cartographer looking for a road beyond the island.', () => enterRoute('vesper')],
127:       ['Walk with Mara through the moon garden.', 'A gardener making plans for a life of her own.', () => enterRoute('mara')],
128:       ['Ask about the heart-tide.', 'Find out how to break the spell before choosing anyone.', () => { state.node = 'truth'; state.chapter = 2; render(); }]
129:     ] });
130:   } else if (state.node === 'route' && state.route) {
131:     const person = cast[state.route];
132:     displayScene({ eyebrow: `${person.name.toUpperCase()} · THE ${person.role.toUpperCase()}`, title: person.title, text: person.text, quote: person.quote, choices: person.choices.map(([label, detail, points]) => [label, detail, () => { state.bond = points; state.node = 'commit'; state.chapter = 3; render(); }]) });
133:   } else if (state.node === 'commit' && state.route) {
134:     const person = cast[state.route];
135:     displayScene({ eyebrow: 'GEYROPOA · BEFORE DAWN', title: 'What will you choose?', text: `${person.name} stands with you at the edge of the shore. The heart-tide is fading. Soon, the island’s pull will be gone, and every feeling left here will belong to the person who feels it.\n\n${person.name} meets your eyes. “I care for you,” she says. “But I want your answer to be yours. What do you want our story to be?”`, quote: person.quote, choices: [
136:       ['Choose a romance together.', 'Be honest about the feelings you want to explore.', () => ending('romance')],
137:       ['Choose a lasting friendship.', 'Care for each other without becoming a couple.', () => ending('friend')],
138:       ['Set out alone.', 'Decline romance and leave room for everyone to choose freely.', () => ending('solo')]
139:     ] });
140:   } else if (state.node === 'truth') {
141:     state.screen = 'story';
142:     displayScene({ eyebrow: 'GEYROPOA · THE ISLAND’S HEART', title: 'The spell beneath the tide', text: 'At the island’s center, you find a pool of black water ringed with old runes. Vesper’s map fits the stones. The heart-tide is not a curse exactly—it magnifies longing until it feels like destiny.\n\nThe three women can break it, but only if someone speaks the thing the spell cannot understand: love is a choice, not a debt. You could say the words and leave all three free to discover what they truly feel.', quote: 'The tide stills. The island waits.', choices: [['Break the heart-tide.', 'Give every heart back to its owner.', () => ending('truth')]] });
143:   } else if (state.node === 'ending') {
144:     state.screen = 'ending';
145:     ending(state.endingType || 'truth');
146:   }
147: }
