     cast: {
       lyra: { name: 'Lyra', role: 'Deniz feneri bekçisi', initial: 'L', avatar: 'lyra', title: 'Söndürmediği ışık', quote: '“Yalnızca ışığımı değil, beni de gören birini istiyorum.”', text: 'Adanın ucunda Lyra, yüz yıldır ışığı yanmayan bir deniz fenerine göz kulak oluyor. Alevi sönmüş değil; adanın nasıl bir yer olacağına birinin karar vermesini bekliyor.\n\nKalp gelgitinin ona sana âşık olduğundan emin hissettirdiğini itiraf ediyor. Bu duygu hâlâ içinde, ama büyünün kimseyi sürüklemediği bir anda geriye ne kalacağını bilmek istiyor.', choices: [['Feneri birlikte yeniden yakmasına yardım et.', 'İşi paylaşır, cesur görünüşünün ardındaki umudu görmesine izin verirsin.', 1], ['Ada özgür olsaydı ne yapacağını sor.', 'Lyra ilk kez kendi istediği gelecekten söz eder.', 0]], romance: ['Birlikte fenerle ilgileniyorsunuz; bekçiyle misafir olarak değil, kalmaya karar vermiş iki insan olarak. Yeni ışığı ana karaya ulaştığında Lyra elini tutuyor. Ada hâlâ gizemli; her yeni şafağı birlikte karşılama kararınız ise tamamen size ait.', 'Fener, denizin üzerine gümüşten bir yol düşürüyor. Lyra, karşılıksız ve özgürce verilen sevginin nasıl hissettirdiğini keşfetmek için seninle yelken açmayı seçiyor. Geyropoa geride kalırken parmaklarını seninkilere doluyor; hikâyeniz daha yeni başlıyor.'], friend: 'Feneri Lyra’nın emin ellerine bırakıp ona yazacağına söz veriyorsun. Sana bir kez sarılıyor, sonra kendi seçtiği ışığa dönüyor. Bu bir aşk değil; ama daha az değerli de değil.' },
       vesper: { name: 'Vesper', role: 'Haritacı', initial: 'V', avatar: 'vesper', title: 'Ucu olmayan bir harita', quote: '“Buradaki bütün yolları çizdim. Nereye gitmek istediğimi hiç sormadım.”', text: 'Vesper, siyah cam parçalarının üzerine haritalar çiziyor. Çizdiği her yol, kalp gelgitinin başladığı adanın merkezine geri kıvrılıyor. Bu örüntü onu büyülüyor; ne anlama geldiğinden ise sessizce korkuyor.\n\nBüyünün onu seni ilk gördüğü anda âşık ettiğini söylüyor. İkinizden hiçbiri adına bu büyünün karar vermesini istemiyor.', choices: [['Onunla imkânsız yolu takip et.', 'Merakına güveniyor, o da sakladığı haritayı seninle paylaşıyor.', 1], ['Birlikte kaybolmayı tercih ettiğini söyle.', 'Vesper gülüyor ve ilk kez haritayı tamamlamadan bırakıyor.', 0]], romance: ['Harita, BURASI diye işaretlenmiş boş bir yerde sona eriyor. Vesper geri kalanını seninle, haritada olmayan günler boyunca keşfetmek istediğini söylüyor. Henüz adını koymadığı bir göğün altında öpüşüyorsunuz; gelecek, güzel bir bilinmezlik gibi.', 'Vesper atlasını kapatıp seninle açık yola çıkmayı seçiyor. Harita öyle gösterdiği için değil, gerçekten istediği için elini tutuyor. Geyropoa’nın ötesinde her yön yeni.'], friend: 'Vesper sana adadan dışarı çıkan tek bir yolun olduğu küçük bir harita veriyor. “Hazır olduğunda,” diyor. Gerçek bir dostlukla, büyüye ihtiyaç duymadan vedalaşıyorsunuz.' },

content.text:
    { title: 'Gece yarısı pazarı', text: 'Ada pazarı yalnızca ay bulutların ardındayken ortaya çıkıyor. Bu gece tezgâhlarda sıradan şeyler var: sıcak ekmek, yamalı eldivenler, küçük bir pirinç pusula. {name} büyülü hiçbir şey almıyor. Bir satıcının berbat şakasına gülüyor; sıradan bir akşamın ne kadar iyi hissettirmesine kendisi de şaşırıyor.', quote: 'Bu kez seçilmek isteyen hiçbir şey yok.', choices: [['Ekmeği paylaşın ve eve uzun yoldan dönün.', 'Birlikte vakit geçirmeyi, karşılığında söz istemeden seçersin.', 1], ['Ona pusula al ve nereye çevireceğine bırak karar versin.', 'Hediye bir emir değil, davet olabilir.', 0]] },
    { title: 'Kayalıkların altındaki fırtına', text: 'Denizin ötesinden bir fırtına geliyor. Dalgalar taşı sarsarken yağmur dinene dek bir deniz mağarasında bekliyorsunuz. {name}, kalp gelgiti ona dokunmasaydı yaşayabileceği hayattan söz ediyor. Hayal ettiği kişinin gerçekten kendisi olup olmadığını bilmiyor. Sen de biliyormuş gibi davranmıyorsun.', quote: '“Belki de yeni birine dönüşebilirim.”', choices: [['Eski hayatından neleri korumak istediğini sor.', 'Büyünün arzusunu değil, değer verdiği şeyleri dinlersin.', 1], ['Değişmenin geçmişini silmediğini söyle.', 'Geleceğini seçmeden ona güven verirsin.', 0]] },
    { title: 'İki kapılı ev', text: 'Adanın merkezinde, iki kapısı da açık küçük bir ev duruyor: biri kıyıya, diğeri tepelere bakıyor. Eski öyküler, içeri girenin aynı kapıdan çıkması gerektiğini söyler. {name} bunu bir kural saymayı reddediyor. İki odayı da geziyorsunuz ve kimse için kurulmamış bir sofra buluyorsunuz.', quote: 'Bir odadan çıkmanın tek bir yolu yoktur.', choices: [['Hangi manzaranın ona ait gibi hissettirdiğini sor.', 'Yuvanın ne demek olduğunu onun tanımlamasına izin verirsin.', 1], ['İkinizden biri gitmeden önce sofrayı paylaşmayı öner.', 'Yakınlığı sahiplenmeye çevirmeden hayal edersin.', 0]] },
    { title: 'Yaşayanlar için fenerler', text: 'Köylüler; özledikleri, henüz tanışmadıkları insanlar için fenerleri suya bırakmak üzere kıyıda toplanıyor. {name} fenerine isim yazmıyor. Onu bir veda değil, değiştirmekte özgür olduğu bir dilek olarak gelgite bırakıyor. Diğerleri yanında ikinize de yer açıyor.', quote: 'Bir dileği bırakmak, ondan vazgeçmek değildir.', choices: [['Yanında olmamı ister misin diye sor.', 'Varlığını varsayım değil, teklif olarak sunarsın.', 1], ['Kendi fenerini onunkinin yanına bırak.', 'Dileklerinizi ayrı tutarak anı paylaşırsınız.', 0]] },
    { title: 'Gelgitin altındaki yol', text: 'Sular çekilince adanın kalbinin altında soluk taşlardan bir yol beliriyor. Her taş, büyünün kadermiş gibi sunduğu bir sözcüğü taşıyor: muhtaç, seçilmiş, söz verilmiş. {name} taşların etrafından dolaşıyor. Birinin özlemi içinde kaybolmak zorunda kalmadan da önemsemenin mümkün olduğunu söylüyor.', quote: '“Çağrılmak değil, gerçekten karşılaşmak istiyorum.”', choices: [['Ne istediğini sormaya devam edeceğine söz ver.', 'Büyük bir yemin yerine sürekli dürüstlüğü seçersin.', 1], ['İyiliğini hak etmek zorunda olmadığını söyle.', 'Karşılığında borç yaratmayan bir şefkat sunarsın.', 0]] },
    { title: 'İlk ışıktan önce', text: 'Yol, Geyropoa’nın sessiz kalbine ulaşıyor. Gelgit neredeyse durmuş. Adayı birlikte aştınız ama bir sonraki adım artık yalnızca ikinize ait. {name} derin bir nefes alıp içtenlikle nasıl bir yarın sunabileceğini soruyor. Ufuk aydınlanmaya başlıyor.', quote: 'Artık ikinizin yerine hiçbir büyü yanıt veremez.', choices: [['Bunu birlikte keşfetmeye devam etmek istediğini söyle.', 'Umudunu dile getirir, karşılığında borç istemezsin.', 1], ['Bir yanıttan çok onun özgürlüğünü istediğini söyle.', 'Vereceği her karara alan bırakırsın.', 0]] }
  ]
};

