62:   document.querySelector('.cast-title').innerHTML = `${tr('cast')} <span>18+</span>`;
63:   $('restartButton').textContent = tr('restart');
64:   $('choiceHeading').textContent = tr('choiceHeading');
65:   $('playAgainButton').innerHTML = tr('playAgain');
66:   $('titleButton').textContent = tr('titleButton');
67:   $('footerHint').textContent = tr('footerHint');
68:   document.querySelector('.story-footer > span:last-child').innerHTML = `${tr('footerTitle')} <b>✦</b>`;
69:   document.querySelector('.page-footer').innerHTML = `<span>${tr('footerTitle')}</span><span>${tr('footerSub')}</span>`;
