106:   $('castList').innerHTML = Object.entries(activeCast()).map(([key, person]) => `<div class="cast-person ${state.route === key ? 'active' : ''}"><div class="avatar ${person.avatar}">${person.initial}</div><div><span class="person-name">${person.name}</span><span class="person-role">${person.role}</span></div></div>`).join('');
107: }
108: function makeChoice(label, detail, action, glyph = '✦') {
109:   const button = document.createElement('button');
110:   button.className = 'choice-button';
111:   button.innerHTML = `<span class="choice-glyph" aria-hidden="true">${glyph}</span><span>${label}${detail ? `<small>${detail}</small>` : ''}</span>`;
112:   button.addEventListener('click', action);
113:   return button;
