118: function updateGate(allowRender = false) {
119:   if (!$('storyScreen') || $('storyScreen').classList.contains('hidden')) return;
120:   const levelTarget = Math.max(0, (state.chapter - 1) * MIN_LEVEL_MS);
121:   const target = state.node === 'ending' ? Math.max(MIN_ENDING_MS, levelTarget) : levelTarget;
122:   const remaining = Math.max(0, target - (Date.now() - (state.startedAt || Date.now())));
123:   const wasLocked = gateLocked;
124:   gateLocked = remaining > 0;
125:   $('levelGate').classList.toggle('hidden', !gateLocked);
126:   $('choices').classList.toggle('hidden', gateLocked || state.node === 'ending');
127:   $('choiceHeading').classList.toggle('hidden', gateLocked || state.node === 'ending');
128:   $('endingActions').classList.toggle('hidden', gateLocked || state.node !== 'ending');
129:   if (gateLocked) {
130:     const minutes = Math.floor(remaining / 60000);
131:     const seconds = Math.floor((remaining % 60000) / 1000).toString().padStart(2, '0');
132:     const endingGate = state.node === 'ending';
133:     const title = tr(endingGate ? 'endingGateTitle' : 'gateTitle');
134:     const body = tr(endingGate ? 'endingGateBody' : 'gateBody');
135:     $('levelGate').innerHTML = `<strong>${title}</strong>${body} <span class="gate-time">${minutes}:${seconds}</span>`;
136:   }
137:   if (allowRender && wasLocked && !gateLocked) render();
138: }
139: function displayScene({ eyebrow = tr('night'), title, text, quote = '', choices = [], ending = false }) {
140:   openStory();
141:   $('sceneEyebrow').textContent = eyebrow;
142:   $('sceneTitle').textContent = sceneText(title);
143:   $('sceneText').textContent = sceneText(text);
144:   $('sceneQuote').textContent = sceneText(quote);
145:   $('sceneQuote').classList.toggle('hidden', !quote);
146:   $('choiceHeading').classList.toggle('hidden', ending);
147:   $('choices').classList.toggle('hidden', ending);
148:   $('endingActions').classList.toggle('hidden', !ending);
149:   $('choices').replaceChildren();
150:   choices.forEach((choice) => $('choices').appendChild(makeChoice(...choice)));
151:   $('chapterKicker').textContent = ending ? tr('endingKicker') : `${tr('levelPrefix')} ${String(state.chapter).padStart(2, '0')} / ${LEVEL_COUNT}`;
152:   const person = state.route ? activeCast()[state.route] : null;
